// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DÉMO WEBINAIRE — Étape 1 : Détection des PII
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
const body = $input.first().json.body || $input.first().json;

// Données saisies par le volontaire (fictives)
const nom_complet  = body.nom_complet  || body.nom    || '';
const prenom       = body.prenom       || '';
const email        = body.email        || '';
const telephone    = body.telephone    || body.tel    || '';
const adresse      = body.adresse      || '';
const ref_dossier  = body.ref_dossier  || '';
const demande      = body.demande      || body.texte  || body.sujet || '';

// ── Détection des champs PII présents ──
const pii_detectes = [];
if (nom_complet || prenom) pii_detectes.push({ type: 'NOM', valeur: [prenom, nom_complet].filter(Boolean).join(' ').trim() });
if (email)      pii_detectes.push({ type: 'EMAIL',     valeur: email });
if (telephone)  pii_detectes.push({ type: 'TELEPHONE', valeur: telephone });
if (adresse)    pii_detectes.push({ type: 'ADRESSE',   valeur: adresse });
if (ref_dossier)pii_detectes.push({ type: 'REF',       valeur: ref_dossier });

// ── Construire le texte brut (ce qui partirait à l'IA SANS protection) ──
const texte_brut = `
Objet de la demande : ${demande}
Demandeur : ${[prenom, nom_complet].filter(Boolean).join(' ')}
Contact : ${email} — ${telephone}
Adresse : ${adresse}
Référence dossier : ${ref_dossier}
`.trim();

return [{ json: {
  // Données originales
  nom_complet, prenom, email, telephone, adresse, ref_dossier, demande,
  texte_brut,
  // Analyse PII
  pii_detectes,
  nb_pii: pii_detectes.length,
  demo_id: 'DEMO-' + Date.now()
}}];

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DÉMO WEBINAIRE — Étape 2 : Pseudonymisation
// Table de correspondance locale (éphémère)
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
const src = $input.first().json;

// ── Table de correspondance : jeton → valeur réelle ──
const table_reidentification = {};

function pseudonymise(valeur, prefixe, compteur) {
  const jeton = `${prefixe}_${String(compteur).padStart(3,'0')}`;
  table_reidentification[jeton] = valeur;
  return jeton;
}

let cpt = { PERSON: 1, EMAIL: 1, PHONE: 1, ADDR: 1, REF: 1 };

// Appliquer la pseudonymisation
const nom_token   = (src.prenom || src.nom_complet) ? pseudonymise([src.prenom, src.nom_complet].filter(Boolean).join(' '), 'PERSON', cpt.PERSON++) : '';
const email_token  = src.email      ? pseudonymise(src.email,     'EMAIL',  cpt.EMAIL++)  : '';
const phone_token  = src.telephone  ? pseudonymise(src.telephone, 'PHONE',  cpt.PHONE++)  : '';
const addr_token   = src.adresse    ? pseudonymise(src.adresse,   'ADDR',   cpt.ADDR++)   : '';
const ref_token    = src.ref_dossier? pseudonymise(src.ref_dossier,'REF',   cpt.REF++)    : '';

// ── Texte pseudonymisé (seul ce texte part vers l'IA) ──
const texte_pseudonymise = `
Objet de la demande : ${src.demande}
Demandeur : ${nom_token || '[non renseigné]'}
Contact : ${email_token || '[non renseigné]'} — ${phone_token || '[non renseigné]'}
Adresse : ${addr_token || '[non renseigné]'}
Référence dossier : ${ref_token || '[non renseigné]'}
`.trim();

return [{ json: {
  // Textes pour comparaison pédagogique
  texte_brut:          src.texte_brut,
  texte_pseudonymise,
  // Mapping pour ré-identification
  table_reidentification,
  // Jetons
  nom_token, email_token, phone_token, addr_token, ref_token,
  // Données originales conservées localement
  nom_original:    [src.prenom, src.nom_complet].filter(Boolean).join(' '),
  email_original:  src.email,
  phone_original:  src.telephone,
  addr_original:   src.adresse,
  ref_original:    src.ref_dossier,
  demande:         src.demande,
  demo_id:         src.demo_id,
  nb_pii_proteges: src.nb_pii
}}];

